input.sparql:
SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(str(?s) CONTAINS "Zone_F2_Z01" || str(?o) CONTAINS "Zone_F2_Z01")
}

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(str(?s) CONTAINS "Core" || str(?o) CONTAINS "Core")
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?p ?o WHERE {
  ?point a brick:Zone_Air_Temperature_Sensor ; brick:isPointOf ?zone .
  ?zone brick:hasPart ?nothing .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  VALUES ?o {
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z01>
  }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?label WHERE {
  ?zone brick:hasPoint ?somepoint .
  ?zone rdfs:label ?label .
}
